# IES Training · MikroTik · L29 · Chequeo de conectividad en escalera
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
# Solo lee y pingea: no toca la configuracion.
{
:local host "{{LAN_HOST}}"
:local lanif "{{LAN_IF}}"
:local lanip "{{LAN_IP_ROUTER}}"
:local ipnet "{{IP_INTERNET}}"
:local nombre "{{NOMBRE}}"
:local falla "ninguna"
# 1. LAN (si no contesta ping, probamos ARP)
:local r1 [/ping $host count=3]
:if ($r1 = 0) do={
  :local a [/ping $host arp-ping=yes interface=$lanif count=2]
  :if ($a = 0) do={ :set falla "1 LAN: cable, puerto o bridge" } else={ :put "El equipo contesta ARP: esta vivo, bloquea el ping." }
}
# 2. Gateway de la ruta por defecto activa
:local rt [/ip/route/find where dst-address=0.0.0.0/0 active]
:local gw ""
:if ([:len $rt] > 0) do={ :set gw [:tostr [/ip/route/get [:pick $rt 0] gateway]] }
:if ([:typeof [:toip $gw]] = "ip") do={
  :if (([/ping $gw count=3] = 0) and ($falla = "ninguna")) do={ :set falla "2 gateway: WAN, modem, VLAN o PPPoE" }
} else={ :put ("Gateway sin IP (" . $gw . "): escalon 2 salteado.") }
# 3. IP de internet
:if (([/ping $ipnet count=3] = 0) and ($falla = "ninguna")) do={ :set falla "3 internet: ruta por defecto o proveedor" }
# 4. Nombre (si no resuelve, ping corta el script: lo atajamos)
:do { :if (([/ping $nombre count=3] = 0) and ($falla = "ninguna")) do={ :set falla "4 nombre: sin respuesta" } } on-error={ :if ($falla = "ninguna") do={ :set falla "4 nombre: DNS (resolve failed)" } }
# 5. Desde la IP de la LAN: prueba el masquerade
:if ([/ping $ipnet src-address=$lanip count=3] = 0) do={ :put "Ojo: desde la IP de la LAN no hay respuesta. Revisar masquerade." }
# 6. MTU del camino, sin fragmentar
:local mtu 0
:foreach s in={1500;1492;1480;1450;1400} do={
  :if ($mtu = 0) do={ :if ([/ping $ipnet size=$s do-not-fragment count=2] > 0) do={ :set mtu $s } }
}
:put ("MTU del camino: " . $mtu . " (0 = ninguna probada paso)")
:put ("Listo: primera falla = " . $falla . ". Para ver los saltos: /tool/traceroute " . $ipnet . " count=3")
}

# IES Training · MikroTik · L30 · DNS del router
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
{
:local dns1 "{{DNS1}}"
:local dns2 "{{DNS2}}"
:local nvrname "{{NOMBRE_NVR}}"
:local nvrip "{{IP_NVR}}"
# 1. Primero el candado: el 53 cerrado desde la WAN
:local defconf [:len [/ip/firewall/filter/find comment="defconf: drop all not coming from LAN"]]
:if ($defconf = 0) do={
  :if ([:len [/interface/list/find name=WAN]] = 0) do={ :error "No existe la lista WAN: crearla antes de seguir." }
  :foreach p in={"udp";"tcp"} do={
    :if ([:len [/ip/firewall/filter/find comment=("ies-dns-wan-" . $p)]] = 0) do={
      :if ([:len [/ip/firewall/filter/find]] > 0) do={
        /ip/firewall/filter/add chain=input in-interface-list=WAN protocol=$p dst-port=53 action=drop comment=("ies-dns-wan-" . $p) place-before=[:pick [/ip/firewall/filter/find] 0]
      } else={
        /ip/firewall/filter/add chain=input in-interface-list=WAN protocol=$p dst-port=53 action=drop comment=("ies-dns-wan-" . $p)
      }
    }
  }
  :put "Sin regla de fabrica: agregue drop del 53 UDP y TCP desde la WAN."
} else={ :put "Esta la regla de fabrica: el 53 ya esta cerrado desde la WAN." }
# 2. Servidores y DNS para la LAN
/ip/dns/set servers=($dns1 . "," . $dns2) allow-remote-requests=yes
# 3. Nombre local del NVR (si existe, se actualiza)
:local e [/ip/dns/static/find name=$nvrname]
:if ([:len $e] = 0) do={
  /ip/dns/static/add name=$nvrname address=$nvrip comment="ies-nvr-dns"
} else={ /ip/dns/static/set $e address=$nvrip }
/ip/dns/cache/flush
# 4. DoH (opcional): sin respaldo si el servicio se cae. Descomentar y completar:
# /ip/dns/set use-doh-server="<URL-DoH>" verify-doh-cert=yes
:do { :put ("Prueba: mikrotik.com = " . [:resolve mikrotik.com]) } on-error={ :put "Ojo: no resuelve. Revisar servidores y salida a internet." }
:put ("Listo: DNS " . $dns1 . " y " . $dns2 . ", " . $nvrname . " = " . $nvrip . ". Verifica con /ip/dns/print")
}

# IES Training · MikroTik · L31 · DNS transparente
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
{
:local exc "{{EXCEPCION}}"
:local lan "{{LISTA_LAN}}"
# Sin resolver para la LAN, redirigir dejaria a todos sin nombres
:if (![/ip/dns/get allow-remote-requests]) do={ :error "allow-remote-requests esta en no: configurar el DNS del router primero (leccion de DNS)." }
:if ([:len [/interface/list/find name=$lan]] = 0) do={ :error ("No existe la lista " . $lan) }
# 1. Excepciones
:if ([:len [/ip/firewall/address-list/find list=dns-libre address=$exc]] = 0) do={
  /ip/firewall/address-list/add list=dns-libre address=$exc comment="ies-dns-libre"
}
# 2. Redireccion UDP y TCP 53 al router
:foreach p in={"udp";"tcp"} do={
  :if ([:len [/ip/firewall/nat/find comment=("ies-dns-transparente-" . $p)]] = 0) do={
    /ip/firewall/nat/add chain=dstnat in-interface-list=$lan src-address-list=!dns-libre dst-address-type=!local protocol=$p dst-port=53 action=redirect to-ports=53 comment=("ies-dns-transparente-" . $p)
  }
}
# 3. Firefox: no prender DoH por su cuenta
:if ([:len [/ip/dns/static/find name="use-application-dns.net"]] = 0) do={
  /ip/dns/static/add name=use-application-dns.net type=NXDOMAIN comment="ies-canario-firefox"
}
# 4. DNS sobre TLS (853): reject para que vuelvan al 53
:if ([:len [/ip/firewall/filter/find comment="ies-sin-dot"]] = 0) do={
  /ip/firewall/filter/add chain=forward in-interface-list=$lan protocol=tcp dst-port=853 action=reject reject-with=icmp-admin-prohibited comment="ies-sin-dot"
}
:put ("Listo: 53 de " . $lan . " redirigido al router, excepcion " . $exc . ". Verifica con /ip/firewall/nat/print stats where comment~\"ies-dns\"")
}

# IES Training · MikroTik · L32 · Adlist y bloqueo de un sitio
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
{
:local cache [:tonum "{{CACHE_KIB}}"]
:local sitio "{{SITIO}}"
:local url "{{URL_ADLIST}}"
# 1. Version: adlist existe desde 7.15
:local v [/system/resource/get version]
:local p [:find $v "."]
:local mayor [:tonum [:pick $v 0 $p]]
:local resto [:pick $v ($p + 1) [:len $v]]
:local fin [:find $resto "."]
:if ([:typeof $fin] = "nil") do={ :set fin [:find $resto " "] }
:local menor [:tonum [:pick $resto 0 $fin]]
:local conadlist (($mayor > 7) or (($mayor = 7) and ($menor >= 15)))
:put ("RouterOS " . $v . " en " . [/system/resource/get architecture-name])
# 2. Cache: solo se sube, nunca se baja
:if ([/ip/dns/get cache-size] < $cache) do={ /ip/dns/set cache-size=$cache }
# 3. Adlist por URL (si la completaste y la version la soporta)
:if (($url != "") and $conadlist) do={
  :if ([:len [/ip/dns/adlist/find url=$url]] = 0) do={ /ip/dns/adlist/add url=$url }
} else={ :if (!$conadlist) do={ :put "Ojo: esta version no tiene adlist. Actualizar a 7.15 o mas." } }
# 4. Sitio entero con subdominios
:if ([:len [/ip/dns/static/find name=$sitio type=NXDOMAIN]] = 0) do={
  /ip/dns/static/add name=$sitio type=NXDOMAIN match-subdomain=yes comment="ies-bloqueo-sitio"
}
/ip/dns/cache/flush
:if ($conadlist) do={ /ip/dns/adlist/print }
:put ("Listo: " . $sitio . " bloqueado con subdominios, cache " . [/ip/dns/get cache-size] . " KiB. Verifica con nslookup " . $sitio . " 192.168.88.1")
}
